question.answer:
package main

import "fmt"

// Server holds the settings a caller may set directly or through options.
type Server struct {
	Addr        string
	ReadTimeout int
}

// Option applies one setting to a Server.
type Option func(*Server)

// WithAddr sets the address the server listens on.
func WithAddr(addr string) Option {
	return func(s *Server) {
		s.Addr = addr
	}
}

// WithReadTimeout sets the read timeout, counted in seconds.
func WithReadTimeout(seconds int) Option {
	return func(s *Server) {
		s.ReadTimeout = seconds
	}
}

// NewServer returns a Server with every option applied in order.
func NewServer(opts ...Option) *Server {
	s := &Server{}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// String reports the settings in force, resolving both defaults as it runs.
func (s *Server) String() string {
	addr := s.Addr
	if addr == "" {
		addr = ":http"
	}
	timeout := "off"
	if s.ReadTimeout > 0 {
		timeout = fmt.Sprintf("%ds", s.ReadTimeout)
	}
	return addr + " " + timeout
}

