question.answer:
package main

import (
	"errors"
	"fmt"
	"io"
	"strings"
)

// ErrTooFewSeats reports a booking below the ledger's minimum.
var ErrTooFewSeats = errors.New("too few seats")

// ErrNoRef reports a booking that carries no reference.
var ErrNoRef = errors.New("no reference")

// Booking is one seat reservation on a sailing.
type Booking struct {
	Ref   string
	Seats int
}

// Ledger hands out the bookings held for one sailing.
type Ledger struct {
	name     string
	bookings []Booking
	pos      int
	minSeats int
}

// Option applies one setting to a Ledger.
type Option func(*Ledger)

// WithMinSeats sets the smallest booking the ledger will hand out.
func WithMinSeats(n int) Option {
	return func(l *Ledger) {
		l.minSeats = n
	}
}

// NewLedger returns a named Ledger over bookings, with every option applied.
func NewLedger(name string, bookings []Booking, opts ...Option) *Ledger {
	l := &Ledger{name: name, bookings: bookings, minSeats: 1}
	for _, opt := range opts {
		opt(l)
	}
	return l
}

// Next returns the next booking, or an error naming this ledger.
func (l *Ledger) Next() (Booking, error) {
	if l.pos >= len(l.bookings) {
		return Booking{}, io.EOF
	}
	b := l.bookings[l.pos]
	l.pos++
	if b.Ref == "" {
		return Booking{}, fmt.Errorf("ledger %s: entry %d: %w", l.name, l.pos, ErrNoRef)
	}
	if b.Seats < l.minSeats {
		return Booking{}, fmt.Errorf("ledger %s: booking %s: %w", l.name, b.Ref, ErrTooFewSeats)
	}
	return b, nil
}

// repeatSource yields one booking a fixed number of times.
type repeatSource struct {
	booking Booking
	left    int
}

// Next returns the held booking until the count runs out.
func (r *repeatSource) Next() (Booking, error) {
	if r.left <= 0 {
		return Booking{}, io.EOF
	}
	r.left--
	return r.booking, nil
}

// Repeat returns a Source yielding b exactly n times.
func Repeat(b Booking, n int) Source {
	return &repeatSource{booking: b, left: n}
}

// Source is what Manifest needs from a booking store.
type Source interface {
	Next() (Booking, error)
}

// Manifest lists every accepted booking and counts the rejected ones.
func Manifest(src Source) (string, error) {
	var parts []string
	rejected := 0
	for {
		b, err := src.Next()
		switch {
		case errors.Is(err, io.EOF):
			parts = append(parts, fmt.Sprintf("rejected %d", rejected))
			return strings.Join(parts, "; "), nil
		case errors.Is(err, ErrTooFewSeats):
			rejected++
		case err != nil:
			return "", fmt.Errorf("manifest: %w", err)
		default:
			parts = append(parts, fmt.Sprintf("%s x%d", b.Ref, b.Seats))
		}
	}
}
